var o=165;var i=`165-mirepoix-sofrito-and-aromatic-bases`;var a=`161`;var r={en:`Mirepoix, Sofrito, and Aromatic Bases`,ua:`Мірпуа, софрито та ароматичні основи`};var s={short:`Aromatic vegetables create the supporting flavor layer in stocks, soups, and sauces. The classical French mirepoix of onion, carrot, and celery is one example among many regional flavor bases.`,sections:[{title:`Core idea`,text:`An aromatic base supplies sweetness, savory depth, herbaceous notes, and sometimes acidity. French mirepoix commonly uses onion, carrot, and celery; Italian soffritto, Spanish sofrito, and other combinations differ in ingredients and preparation.`},{title:`Scientific / practical principles`,text:`Cut size affects extraction speed and texture. Gentle sweating releases water and softens vegetables with minimal browning; higher heat encourages browning and a roasted flavor. Garlic and delicate herbs may turn harsh or lose aroma if cooked too long.`},{title:`How to apply it`,text:`Choose the base to match the intended dish. Cut vegetables uniformly; sweat in modest fat for an aromatic soup, or roast for a brown stock. Use herbs in a bundle or sachet when you want to remove them cleanly.`},{title:`Practical example`,text:`Cook equal onion-carrot-celery mixes in two pans: one slowly, covered, without color; the other over higher heat until lightly browned. Add equal water, simmer briefly, and compare the two aromatic profiles.`},{title:`Common mistakes and limitations`,text:`Mirepoix is a technique and flavor pattern, not a rule every cuisine must follow. Too much carrot may make a sauce unexpectedly sweet; using spoiled vegetable trimmings is unsafe; very small dice may disintegrate during prolonged simmering.`},{title:`Regional distinction`,text:`French mirepoix often uses onion, carrot and celery, while a Spanish-style sofrito may build flavor from onion, garlic, peppers and tomato slowly cooked in oil. Neither is universal; choose aromatics that fit the culinary tradition and final dish.`},{title:`Related theories`,text:`067, 161, 162, 171.`}]};var n={short:`Ароматичні овочі створюють базовий смаковий шар бульйонів, супів і соусів. Класичний французький мірпуа з цибулі, моркви та селери є лише одним із багатьох регіональних варіантів.`,sections:[{title:`Суть`,text:`Овочева основа додає солодкість, глибину, трав’янисті ноти, іноді кислотність. Французький мірпуа зазвичай складається з цибулі, моркви й селери; італійське софрито, іспанське софріто та інші суміші мають власні складники й спосіб обробки.`},{title:`Наукові та практичні принципи`,text:`Розмір нарізання впливає на швидкість віддавання смаку й текстуру. Повільне пасерування випаровує частину вологи та пом’якшує овочі без сильного підрум’янення, а інтенсивний жар створює обсмажені відтінки. Часник і ніжна зелень можуть втратити приємний аромат.`},{title:`Як застосовувати`,text:`Обирайте основу відповідно до страви. Рівномірно нарізайте овочі; для ніжного супу повільно пасеруйте в невеликій кількості жиру, для темної основи підрум’янюйте. Зелень зручно збирати в букет або мішечок.`},{title:`Практичний приклад`,text:`Однакову суміш цибулі, моркви та селери приготуйте двома способами: повільно без скоринки та швидше до підрум’янення. Додайте однакову кількість води, трохи проваріть і порівняйте аромат.`},{title:`Поширені помилки й обмеження`,text:`Мірпуа не є обов’язковою основою кухонь світу. Забагато моркви зробить соус солодким; зіпсовані овочеві обрізки неприпустимі, а надто дрібно нарізані овочі розваряться під час довгого готування.`},{title:`Регіональні відмінності`,text:`Французьке мірпуа часто складається з цибулі, моркви та селери, тоді як іспанське софрито може містити цибулю, часник, перець і томати, повільно приготовані в олії. Жодна основа не є універсальною: добирайте її під страву та кулінарну традицію.`},{title:`Пов’язані теорії`,text:`067, 161, 162, 171.`}]};var l=[67,161,162,171];var c=`References / Джерела`;var m=[`https://www.theculinarypro.com/stocks-soups-and-sauces-1`,`https://www.theculinarypro.com/soups`];var d={id:165,slug:i,group:`161`,title:r,en:s,ua:n,related:l,referenceTitle:c,references:m};export{d as default,s as en,a as group,o as id,c as referenceTitle,m as references,l as related,i as slug,r as title,n as ua};